'use client';
import { useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Avatar, Spin, Swap } from '../lib/motion';
import '../designme.css';
import './task-table.css';

export type TaskStatus = 'running' | 'failed' | 'queued' | 'paused' | 'done';

export interface Task {
  id: string;
  /** What the agent is doing, like "Audit pricing contrast" */
  name: string;
  status: TaskStatus;
  /** The agent on it, shown as a small avatar and a name */
  agent: { name: string; initials: string; color: string };
  /** In dollars, shown as $0.42 */
  cost: number;
  /** Minutes since it last changed, shown as "14m ago", or "Just now" at 0 */
  updated: number;
}

export type TaskSortKey = 'name' | 'status' | 'agent' | 'cost' | 'updated';
export interface TaskSort { key: TaskSortKey; desc?: boolean }
export type TaskAction = 'pause' | 'retry' | 'cancel';

export interface TaskTableProps {
  tasks: Task[];
  /** The name in the header. Defaults to "Agent tasks" */
  title?: string;
  /** The quiet line beside the name. Defaults to a count of tasks and how many are running */
  summary?: string;
  /** Ids of the selected tasks. Leave it out to let the checkboxes and rows toggle it */
  selected?: string[];
  defaultSelected?: string[];
  onSelectedChange?: (ids: string[]) => void;
  /** The column the rows are sorted by. Leave it out to let the headers set it. Defaults to updated, newest first */
  sort?: TaskSort;
  defaultSort?: TaskSort;
  onSortChange?: (sort: TaskSort) => void;
  /** A button in the header while tasks are selected. The selection clears after it; cancelled rows slide away first */
  onAction?: (action: TaskAction, ids: string[]) => void;
  /** What shows when there are no tasks. Defaults to a short "No agent tasks" note */
  empty?: ReactNode;
  /** A button under the empty note, like { label: 'Bring them back', onClick } */
  emptyAction?: { label: string; onClick: () => void };
  className?: string;
}

const STATUS: Record<TaskStatus, { label: string; rank: number; tone: string; glyph: () => ReactNode }> = {
  running: { label: 'Running', rank: 0, tone: 'run', glyph: () => <Spin /> },
  failed: { label: 'Failed', rank: 1, tone: 'fail', glyph: () => <Icon name="alert" size="xs" /> },
  queued: { label: 'Queued', rank: 2, tone: 'wait', glyph: () => <span className="dm-dot" /> },
  paused: { label: 'Paused', rank: 3, tone: 'pause', glyph: () => <Icon name="pause" size="xs" /> },
  done: { label: 'Done', rank: 4, tone: 'done', glyph: () => <Icon name="ok" size="xs" /> }
};
const COLUMNS: { key: TaskSortKey; label: string; right?: boolean }[] = [
  { key: 'name', label: 'Task' }, { key: 'status', label: 'Status' }, { key: 'agent', label: 'Agent' },
  { key: 'cost', label: 'Cost', right: true }, { key: 'updated', label: 'Updated', right: true }
];
const FIELD: Record<TaskSortKey, (t: Task) => string | number> = {
  name: t => t.name, status: t => STATUS[t.status].rank, agent: t => t.agent.name, cost: t => t.cost, updated: t => t.updated
};
const ACTIONS: { key: TaskAction; label: string; icon: 'pause' | 'refresh' | 'x' }[] = [
  { key: 'pause', label: 'Pause', icon: 'pause' }, { key: 'retry', label: 'Retry', icon: 'refresh' }, { key: 'cancel', label: 'Cancel', icon: 'x' }
];
const ago = (m: number) => (m ? m + 'm ago' : 'Just now');

/** A tick that springs in, and the dash select-all shows while only some rows are picked */
const Tick = () => <><Icon name="check" size="xs" className="dm-ck-y" /><Icon name="minus" size="xs" className="dm-ck-m" /></>;

/**
 * Agent tasks in a sortable table. Pick rows and the header turns into what you can do to them; rows glide when the
 * order changes, cancelled ones slide away, and an empty table says so.
 */
export function TaskTable({
  tasks, title = 'Agent tasks', summary, selected, defaultSelected = [], onSelectedChange, sort, defaultSort = { key: 'updated' }, onSortChange,
  onAction, empty, emptyAction, className
}: TaskTableProps) {
  const [sel, setSel] = useControllable(selected, defaultSelected, onSelectedChange);
  const [by, setBy] = useControllable(sort, defaultSort, onSortChange);
  const [leaving, setLeaving] = useState<string[]>([]);
  const reduce = useReducedMotion();
  const f = FIELD[by.key];
  const rows = [...tasks].sort((a, b) => { const x = f(a), y = f(b); return (x > y ? 1 : x < y ? -1 : 0) * (by.desc ? -1 : 1); });
  const picked = sel.filter(id => tasks.some(t => t.id === id) && !leaving.includes(id));
  const n = picked.length, all = n === 0 ? 'false' : n === tasks.length ? 'true' : 'mixed';
  // the header keeps its count while it slides back to the title
  const [shown, setShown] = useState(n);
  if (n && n !== shown) setShown(n);
  const running = tasks.filter(t => t.status === 'running').length;
  const line = summary ?? (tasks.length ? `${tasks.length} task${tasks.length === 1 ? '' : 's'}, ${running} running` : 'No tasks');

  // rows glide to their new places: where each row sat in the table is kept after every render and eased from on the next
  const body = useRef<HTMLTableSectionElement>(null);
  const was = useRef(new Map<string, number>());
  useIsoLayoutEffect(() => {
    const now = new Map<string, number>();
    body.current?.querySelectorAll<HTMLTableRowElement>('tr[data-id]').forEach(tr => {
      const id = tr.dataset.id!, top = tr.offsetTop, before = was.current.get(id);
      now.set(id, top);
      if (!reduce && before !== undefined && Math.abs(before - top) > 1) tr.animate([{ transform: `translateY(${before - top}px)` }, { transform: 'none' }], { duration: 500, easing: 'cubic-bezier(.22,1,.36,1)' });
    });
    was.current = now;
  });

  // the empty state keeps the height the table had, centred in it, so the card doesn't shrink when the last task goes
  const panel = useRef<HTMLDivElement>(null), emptyCell = useRef<HTMLTableCellElement>(null);
  const full = useRef<number | undefined>(undefined);
  const [pad, setPad] = useState<{ paddingTop: number; paddingBottom: number }>();
  useIsoLayoutEffect(() => { if (tasks.length && panel.current) full.current = panel.current.offsetHeight; });
  useIsoLayoutEffect(() => {
    const p = panel.current, td = emptyCell.current;
    if (tasks.length || !p || !td || !full.current) { setPad(undefined); return; }
    const d = full.current - p.offsetHeight, cs = getComputedStyle(td);
    setPad(d > 1 ? { paddingTop: parseFloat(cs.paddingTop) + d / 2, paddingBottom: parseFloat(cs.paddingBottom) + d / 2 } : undefined);
  }, [tasks.length === 0]); // eslint-disable-line react-hooks/exhaustive-deps

  const toggle = (id: string) => setSel(sel.includes(id) ? sel.filter(x => x !== id) : [...sel, id]);
  const sortBy = (key: TaskSortKey) => setBy(key === by.key ? { key, desc: !by.desc } : { key, desc: false });
  const act = (a: TaskAction) => {
    const ids = picked; setSel([]);
    if (a !== 'cancel' || reduce) { onAction?.(a, ids); return; }
    setLeaving(ids);
    setTimeout(() => { onAction?.(a, ids); setLeaving([]); }, 250);
  };

  return (
    <div data-dm="" className={cx('dm-ttx-box', className)} style={{ containerType: 'inline-size', width: '100%' }}>
      <div ref={panel} className={cx('dm-ttx dm-panel', n > 0 && 'dm-selecting')}>
        <div className="dm-ttx-hd">
          <div className="dm-ttx-ti" inert={n > 0}><b>{title}</b><Swap className="dm-muted dm-num dm-ttx-sum">{line}</Swap></div>
          <div className="dm-ttx-sb" inert={n === 0}>
            <span className="dm-ttx-n dm-num">{shown} selected</span>
            {ACTIONS.map(a => (
              <button key={a.key} type="button" className={cx('dm-pill dm-ghost dm-sm', a.key === 'cancel' && 'dm-ttx-del')} onClick={() => act(a.key)}><Icon name={a.icon} size="xs" />{a.label}</button>
            ))}
            <span className="dm-ttx-sp" />
            <button type="button" className="dm-pill dm-ghost dm-sm dm-ttx-clr" onClick={() => setSel([])}>Clear</button>
          </div>
        </div>
        <div className="dm-ttx-sc">
          <table className="dm-ttx-t">
            <thead>
              <tr>
                <th className="dm-ck">
                  <button type="button" className="dm-ttx-cb dm-ttx-all" role="checkbox" aria-checked={all} aria-label="Select all" onClick={() => setSel(all === 'true' ? [] : tasks.map(t => t.id))}><Tick /></button>
                </th>
                {COLUMNS.map(c => (
                  <th key={c.key} className={c.right ? 'dm-r' : undefined} aria-sort={by.key === c.key ? (by.desc ? 'descending' : 'ascending') : 'none'}>
                    <button type="button" className={cx('dm-ttx-s', by.key === c.key && 'dm-on', by.desc && 'dm-desc')} onClick={() => sortBy(c.key)}>
                      {c.label}<span className="dm-ar"><Icon name="chev-u" size="xs" /></span>
                    </button>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody ref={body}>
              {rows.map((t, i) => {
                const on = picked.includes(t.id), st = STATUS[t.status];
                return (
                  <tr key={t.id} data-id={t.id} className={cx('dm-enter', on && 'dm-sel', leaving.includes(t.id) && 'dm-ttx-out')} style={{ animationDelay: i * 30 + 'ms' }} onClick={() => toggle(t.id)}>
                    <td className="dm-ck">
                      <button type="button" className="dm-ttx-cb" role="checkbox" aria-checked={on} aria-label={'Select ' + t.name}><Tick /></button>
                    </td>
                    <td className="dm-nm">{t.name}</td>
                    <td><span className="dm-ttx-st" data-s={st.tone}><span key={t.status} className="dm-sv dm-ttx-sin">{st.glyph()}<span>{st.label}</span></span></span></td>
                    <td><span className="dm-ag"><Avatar initials={t.agent.initials} color={t.agent.color} />{t.agent.name}</span></td>
                    <td className="dm-r dm-num">${t.cost.toFixed(2)}</td>
                    <td className="dm-r dm-num dm-up"><Swap>{ago(t.updated)}</Swap></td>
                  </tr>
                );
              })}
              {!tasks.length && (
                <tr className="dm-ttx-empty dm-enter">
                  <td colSpan={6} ref={emptyCell} style={pad}>
                    {empty ?? (
                      <div className="dm-ttx-em">
                        <span className="dm-ic"><Icon name="check" /></span>
                        <b>No agent tasks</b>
                        <span>Everything has finished or been cancelled.</span>
                        {emptyAction && <button type="button" className="dm-pill dm-ghost dm-sm" onClick={emptyAction.onClick}><Icon name="refresh" size="xs" />{emptyAction.label}</button>}
                      </div>
                    )}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Task table ---------- */
.dm-ttx{overflow:hidden;position:relative;container:ttx/inline-size}
/* the header holds the table's name and a summary, or, while rows are picked, what you can do to them */
.dm-ttx-hd{position:relative;height:50px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ttx-ti,.dm-ttx-sb{position:absolute;inset:0;display:flex;align-items:center;transition:opacity .28s var(--dm-ease),transform .45s var(--dm-ease),filter .28s var(--dm-ease)}
.dm-ttx-ti{gap:10px;padding:0 var(--dm-s-4)}
.dm-ttx-ti b{font-size:13.5px;font-weight:500}
.dm-ttx-sum{font-size:12.5px}
.dm-ttx-sb{gap:2px;padding:0 10px 0 var(--dm-s-4);opacity:0;transform:translateY(10px);filter:blur(3px);pointer-events:none}
.dm-ttx.dm-selecting .dm-ttx-ti{opacity:0;transform:translateY(-10px);filter:blur(3px);pointer-events:none}
.dm-ttx.dm-selecting .dm-ttx-sb{opacity:1;transform:none;filter:none;pointer-events:auto}
.dm-ttx-n{margin-right:var(--dm-s-2);font-size:13px;font-weight:500;white-space:nowrap}
.dm-ttx-sp{flex:1}
.dm-ttx-sb .dm-pill.dm-ttx-del{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.dm-ttx-sb .dm-pill.dm-ttx-del:hover{background:color-mix(in srgb,var(--dm-bad) 10%,transparent);color:var(--dm-bad)}}
.dm-ttx-sc{overflow-x:auto}
.dm-ttx-t{width:100%;border-collapse:collapse;font-size:13px;min-width:560px}
.dm-ttx-t th{height:36px;padding:0 var(--dm-s-2);text-align:left;font-weight:500;font-size:12px;color:var(--dm-muted);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);white-space:nowrap}
.dm-ttx-t th.dm-ck,.dm-ttx-t td.dm-ck{width:36px;padding-left:var(--dm-s-4)}
.dm-ttx-t th.dm-r,.dm-ttx-t td.dm-r{text-align:right}
.dm-ttx-t th:last-child,.dm-ttx-t td:last-child{padding-right:var(--dm-s-4)}
/* a header sorts its column: a quiet arrow shows on hover and stays on the column the rows are sorted by */
.dm-ttx-s{display:inline-flex;align-items:center;gap:3px;height:24px;margin:0 -6px;padding:0 6px;border-radius:calc(6px * var(--dm-rk));color:inherit;font:inherit;transition:color .2s,background-color .2s}
@media (hover:hover) and (pointer:fine){.dm-ttx-s:hover{color:var(--dm-fg);background:var(--dm-row)}}
.dm-ttx-s .dm-ar{display:grid;opacity:0;transition:opacity .2s,transform .35s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-ttx-s:hover .dm-ar{opacity:.45}}
.dm-ttx-s.dm-on{color:var(--dm-fg)}
.dm-ttx-s.dm-on .dm-ar{opacity:1}
.dm-ttx-s.dm-on.dm-desc .dm-ar{transform:rotate(180deg)}
.dm-ttx-t td{height:46px;padding:0 var(--dm-s-2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);white-space:nowrap}
.dm-ttx-t tbody tr:last-child td{border-bottom:0}
/* rows: the shared hover, and a slightly deeper grey while picked */
.dm-ttx-t tbody tr[data-id]{cursor:pointer;transition:background-color .25s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-ttx-t tbody tr[data-id]:hover{background:var(--dm-row)}}
.dm-ttx-t tbody tr.dm-sel{background:color-mix(in srgb,var(--dm-fg) 6%,transparent)}
@media (hover:hover) and (pointer:fine){.dm-ttx-t tbody tr.dm-sel:hover{background:color-mix(in srgb,var(--dm-fg) 8%,transparent)}}
.dm-ttx-t .dm-nm{font-weight:500}
.dm-ttx-t .dm-ag{display:flex;align-items:center;gap:7px;color:var(--dm-fg2)}
.dm-ttx-t .dm-ag .dm-av{width:20px;height:20px;font-size:9.5px}
.dm-ttx-t td.dm-num{color:var(--dm-fg2)}
.dm-ttx-t td.dm-up{color:var(--dm-muted)}
/* checkboxes: the tick springs in; select-all shows a dash while only some rows are picked */
.dm-ttx-cb{display:grid;place-items:center;width:16px;height:16px;border-radius:5px;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface));color:var(--dm-on-accent,#fff);transition:background-color .2s,box-shadow .2s}
@media (hover:hover) and (pointer:fine){.dm-ttx-cb:hover{box-shadow:inset 0 0 0 1.5px var(--dm-muted)}}
.dm-ttx-cb[aria-checked="true"],.dm-ttx-cb[aria-checked="mixed"]{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent))}
.dm-ttx-cb svg{grid-area:1/1;width:11px;height:11px;opacity:0;transform:scale(.4);transition:opacity .15s,transform .3s cubic-bezier(.34,1.4,.64,1)}
.dm-ttx-cb[aria-checked="true"] .dm-ck-y,.dm-ttx-cb[aria-checked="mixed"] .dm-ck-m{opacity:1;transform:none}
/* status: a soft pill in the status colour; Running, Done and Failed have their own, Queued and Paused stay grey */
.dm-ttx-st{--dm-sc:var(--dm-muted);display:inline-flex;align-items:center;height:22px;padding:0 9px 0 7px;border-radius:var(--dm-r-pill);font-size:12px;font-weight:500;color:var(--dm-sc);background:color-mix(in srgb,var(--dm-sc) 11%,transparent);transition:color .35s var(--dm-ease),background-color .35s var(--dm-ease)}
.dm-ttx-st .dm-sv{display:inline-flex;align-items:center;gap:6px}
/* running reads in the accent's text colour on a tint of its mark, so a light accent like lime stays legible */
.dm-ttx-st[data-s="run"]{--dm-sc:var(--dm-accent-fg,var(--dm-accent));background:color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 11%,transparent)}
.dm-ttx-st[data-s="done"]{--dm-sc:var(--dm-ok)}
.dm-ttx-st[data-s="fail"]{--dm-sc:var(--dm-bad)}
.dm-ttx-st .dm-spin{width:10px;height:10px}
/* a new status fades in out of a blur; a cancelled row slides away before it goes */
.dm-ttx-sin{animation:dm-ttxsin .32s var(--dm-ease)}
@keyframes dm-ttxsin{from{opacity:0;filter:blur(3px)}}
.dm-ttx-t tbody tr.dm-ttx-out{opacity:0;transform:translateX(14px);transition:opacity .24s var(--dm-ease),transform .24s var(--dm-ease)}
.dm-ttx-st .dm-i{width:12px;height:12px}
/* when every task is gone */
.dm-ttx-t tbody tr.dm-ttx-empty td{height:auto;padding:36px var(--dm-s-4) 34px;text-align:center;white-space:normal}
.dm-ttx-em{display:flex;flex-direction:column;align-items:center;gap:3px}
.dm-ttx-em .dm-ic{display:grid;place-items:center;width:36px;height:36px;margin-bottom:var(--dm-s-2);border-radius:var(--dm-r-in);background:var(--dm-chip);color:var(--dm-muted)}
.dm-ttx-em b{font-size:13.5px;font-weight:500}
.dm-ttx-em span{font-size:12.5px;color:var(--dm-muted)}
.dm-ttx-em .dm-pill{margin-top:10px}
/* narrow, on a phone or in a narrow card: each task stacks, its name and cost on top and its status, agent and last update
   on a line under it; the header row keeps select all and the sort buttons, and the bulk actions stay in the header above */
@container ttx (max-width:560px){
  .dm-ttx-t{display:block;min-width:0}
  .dm-ttx-t thead,.dm-ttx-t tbody{display:block}
  .dm-ttx-t tr{position:relative;padding:var(--dm-s-3) var(--dm-s-4) var(--dm-s-3) 44px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
  .dm-ttx-t thead tr{display:flex;flex-wrap:wrap;align-items:center;gap:var(--dm-s-1) var(--dm-s-2);padding-top:var(--dm-s-2);padding-bottom:var(--dm-s-2)}
  .dm-ttx-t tbody tr{display:flex;flex-wrap:wrap;align-items:center;gap:var(--dm-s-1) var(--dm-s-3)}
  .dm-ttx-t tbody tr:last-child{border-bottom:0}
  .dm-ttx-t th,.dm-ttx-t td,.dm-ttx-t th:last-child,.dm-ttx-t td:last-child{display:block;height:auto;padding:0;border-bottom:0}
  .dm-ttx-t th.dm-ck,.dm-ttx-t td.dm-ck{position:absolute;left:16px;top:14px;width:auto;padding:0}
  .dm-ttx-t thead th.dm-ck{top:50%;transform:translateY(-50%)}
  .dm-ttx-t td.dm-nm{order:1;flex:1 0 calc(100% - 64px);min-width:0;white-space:normal;line-height:1.45}
  .dm-ttx-t td:nth-child(5){order:2;margin-left:auto;font-size:12px}
  .dm-ttx-t td:nth-child(3){order:3}
  .dm-ttx-t td:nth-child(4){order:4}
  .dm-ttx-t td.dm-up{order:5;margin-left:auto;font-size:12px}
  .dm-ttx-s:not(.dm-on) .dm-ar{display:none}
  .dm-ttx-t tbody tr.dm-ttx-empty{display:block;padding:0}
  .dm-ttx-t tbody tr.dm-ttx-empty td{padding:36px var(--dm-s-4) var(--dm-s-8)}
}
@container ttx (max-width:420px){.dm-ttx-sb{padding-right:var(--dm-s-1)}.dm-ttx-sb .dm-pill{padding:0 var(--dm-s-2)}.dm-ttx-sb .dm-pill .dm-i{display:none}}
@container ttx (max-width:340px){.dm-ttx-ti{padding:0 var(--dm-s-3)}.dm-ttx-sb{gap:0;padding:0 var(--dm-s-1) 0 var(--dm-s-3)}.dm-ttx-n{margin-right:var(--dm-s-1)}.dm-ttx-t tr{padding-left:40px}.dm-ttx-t th.dm-ck,.dm-ttx-t td.dm-ck{left:12px}}
